\label{mk-ch-curves}

Let \(k\) be a field and let \(C\to\Spec k\) be a smooth, proper,
geometrically integral curve.  Write \(K(C)\) for its function field and
\(\mathcal O_C\) for its structure sheaf.

\begin{definition}[Divisor line bundle]
  \label{mk-def-divisor-line-bundle}
  \dcref{II.6}
  \cite{hartshorne-ag}
  For a divisor \(D=\sum n_x[x]\), define
  \(\mathcal O_C(D)_x=\{f\in K(C):\operatorname{ord}_x(f)+n_x\ge0\}\).
\end{definition}

\begin{lemma}[Divisor line bundles are invertible]
  \label{mk-lem-divisor-invertible}
  \dcref{II.6}
  \uses{mk-def-divisor-line-bundle}
  \cite{hartshorne-ag}
  The sheaf \(\mathcal O_C(D)\) is invertible and
  \(\mathcal O_C(D+E)\cong\mathcal O_C(D)\otimes\mathcal O_C(E)\).
\end{lemma}

\begin{proof}
  At \(x\), a uniformizer \(\pi_x\) identifies the stalk with
  \(\pi_x^{-n_x}\mathcal O_{C,x}\), a free rank-one module.  Multiplication in
  \(K(C)\) gives the displayed tensor identification stalkwise, hence globally.
\end{proof}

\begin{lemma}[Principal divisors have degree zero]
  \label{mk-lem-principal-degree-zero}
  \dcref{II.6}
  \uses{mk-def-divisor}
  \cite{hartshorne-ag,papaioannou-rr}
  For \(f\in K(C)^\times\), \(\deg\operatorname{div}(f)=0\).
\end{lemma}

\begin{proof}
  Apply the product formula to the finite extension \(K(C)/k(t)\) after
  choosing a nonconstant \(t\in K(C)\): the sum of valuations of \(f\), each
  weighted by the residue degree, is zero.  The result is independent of the
  chosen \(t\), and is exactly the stated degree.
\end{proof}

\begin{lemma}[The divisor exact sequence]
  \label{mk-lem-divisor-exact-sequence}
  \dcref{II.6}
  \uses{mk-def-divisor-line-bundle}
  \cite{hartshorne-ag}
  If \(P\) is a closed point, there is an exact sequence
  \[
    0\longrightarrow\mathcal O_C(D-P)\longrightarrow\mathcal O_C(D)
    \longrightarrow\kappa(P)\longrightarrow0.
  \]
\end{lemma}

\begin{proof}
  Away from \(P\) the first map is an isomorphism.  At \(P\), write both
  stalks using a uniformizer; the quotient is
  \(\mathcal O_{C,P}/(\pi_P)\cong\kappa(P)\), proving exactness.
\end{proof}

\begin{definition}[Divisors]
  \label{mk-def-divisor}
  \dcref{II.6}
  \cite{hartshorne-ag,papaioannou-rr}
  A Weil divisor on \(C\) is a finite sum \(D=\sum_{x\in C^{(1)}}n_x[x]\),
  \(n_x\in\mathbb Z\).  Its degree is
  \[
    \deg D=\sum_x n_x[\kappa(x):k].
  \]
  For \(f\in K(C)^\times\), \(\operatorname{div}(f)=\sum_x
  \operatorname{ord}_x(f)[x]\) is principal; divisors modulo principal
  divisors form \(\operatorname{Pic}(C)\).
\end{definition}

\begin{definition}[Genus]
  \label{mk-def-genus}
  \dcref{IV.1,custom}
  \cite{milne-av,kleiman-picard}
  The genus of \(C\) is
  \[
    g(C)=\dim_k H^1(C,\mathcal O_C).
  \]
\end{definition}

The finiteness in this definition is a consequence of coherent-cohomology
finiteness for proper schemes; the smoothness and geometric integrality
hypotheses ensure that this agrees with the usual geometric genus.

\begin{theorem}[Riemann--Roch]
  \label{mk-thm-riemann-roch}
  \dcref{IV.1}
  \uses{mk-def-divisor,mk-def-genus}
  \cite{hartshorne-ag,papaioannou-rr}
  There is a canonical divisor \(K_C\) of degree \(2g(C)-2\) and, for every
  divisor \(D\),
  \[
    \ell(D)-\ell(K_C-D)=\deg D+1-g(C),
    \qquad \ell(D)=\dim_k H^0(C,\mathcal O_C(D)).
  \]
\end{theorem}

\begin{proof}
  For a divisor \(D\), Serre duality identifies
  \(H^1(C,\mathcal O_C(D))^\vee\) with
  \(H^0(C,\mathcal O_C(K_C-D))\).  Serre vanishing gives
  \(H^1(C,\mathcal O_C(D))=0\) for all sufficiently large \(D\).  If \(P\) is
  a closed point, the exact sequence
  \[
    0\longrightarrow\mathcal O_C(D-P)\longrightarrow\mathcal O_C(D)
    \longrightarrow\kappa(P)\longrightarrow0
  \]
  shows that the Euler characteristic increases by \([\kappa(P):k]\) when
  \(P\) is added.  Descending from a large divisor therefore gives
  \(\chi(\mathcal O_C(D))=\deg D+\chi(\mathcal O_C)\).  Since
  \(\chi(\mathcal O_C)=1-g(C)\), duality yields the displayed formula.
\end{proof}

\begin{corollary}[Large-degree vanishing]
  \label{mk-cor-large-degree}
  \dcref{IV.1}
  \uses{mk-thm-riemann-roch}
  \cite{hartshorne-ag,papaioannou-rr}
  If \(\deg D>2g(C)-2\), then \(H^1(C,\mathcal O_C(D))=0\) and
  \(\ell(D)=\deg D+1-g(C)\).
\end{corollary}

\begin{proof}
  The dual space to \(H^1(C,\mathcal O_C(D))\) is
  \(H^0(C,\mathcal O_C(K_C-D))\).  Its degree is negative, so it has no
  nonzero section.  Substitution in Riemann--Roch gives the formula for
  \(\ell(D)\).
\end{proof}

\label{mk-ch-cohomology}

For a \(k\)-scheme \(T\), put \(C_T=C\times_kT\).  Cohomology is taken on
the Zariski site (equivalently for quasi-coherent sheaves on the small fppf
site).

\begin{definition}[Module-valued sheaf cohomology]
  \label{mk-def-module-cohomology}
  \dcref{III.1,custom}
  \cite{stacks-cohomology}
  For a sheaf \(\mathcal F\) of \(k\)-modules on \(C\), define
  \(H^i(C,\mathcal F)=\operatorname{Ext}^i(k_C,\mathcal F)\), where \(k_C\)
  is the constant sheaf.
\end{definition}

\begin{proposition}[The Cech short exact sequence]
  \label{mk-prop-cech-short-exact}
  \dcref{III.1}
  \uses{mk-def-cech-complex,mk-lem-affine-h1-vanishing}
  \cite{stacks-cohomology-schemes}
  For an affine cover \(C=U\cup V\) and quasi-coherent \(\mathcal F\),
  \[
    0\to\Gamma(C,\mathcal F)\to\mathcal F(U)\oplus\mathcal F(V)
    \to\mathcal F(U\cap V)\to H^1(C,\mathcal F)\to0.
  \]
\end{proposition}

\begin{proof}
  The first three terms are the sheaf equalizer, and the last two are the
  kernel and cokernel of the Cech differential.  Affine vanishing makes the
  Cech complex compute derived cohomology.
\end{proof}

\begin{definition}[Two-affine Cech complex]
  \label{mk-def-cech-complex}
  \dcref{III.1}
  \cite{stacks-cohomology-schemes}
  For an affine cover \(C=U\cup V\) and a quasi-coherent sheaf \(\mathcal F\),
  set
  \[
    \check C^0(\mathcal F)=\mathcal F(U)\oplus\mathcal F(V),\qquad
    \check C^1(\mathcal F)=\mathcal F(U\cap V),
  \]
  with differential \(d(s,t)=s|_{U\cap V}-t|_{U\cap V}\).
\end{definition}

\begin{lemma}[Cech differential and degree zero]
  \label{mk-lem-cech-differential}
  \dcref{III.1}
  \uses{mk-def-cech-complex}
  \cite{stacks-cohomology-schemes}
  The two-affine complex has no term in degree \(2\), and
  \[
    \check H^0(\mathcal F)=
    \ker\bigl(\mathcal F(U)\oplus\mathcal F(V)\to\mathcal F(U\cap V)\bigr).
  \]
\end{lemma}

\begin{proof}
  There is no degree-two term.  The kernel condition is exactly equality of
  the two restrictions, which is the sheaf gluing condition.
\end{proof}

\begin{proposition}[Two-affine Cech computes cohomology]
  \label{mk-prop-cech-computes}
  \dcref{III.1}
  \uses{mk-def-cech-complex,mk-lem-cech-differential}
  \cite{stacks-cohomology-schemes}
  If \(U,V,U\cap V\) are affine, then
  \[
    H^0(C,\mathcal F)=\check H^0(\mathcal F),\qquad
    H^1(C,\mathcal F)=\operatorname{coker}(d).
  \]
\end{proposition}

\begin{proof}
  A quasi-coherent sheaf is acyclic on each affine in the cover and on their
  intersection.  The Cech-to-derived spectral sequence therefore degenerates
  to the cohomology of the displayed two-term complex.
\end{proof}

\begin{lemma}[Affine vanishing in degree one]
  \label{mk-lem-affine-h1-vanishing}
  \dcref{III.1}
  \cite{stacks-cohomology-schemes}
  For an affine scheme \(W\) and a quasi-coherent sheaf \(\mathcal F\),
  \(H^i(W,\mathcal F)=0\) for every \(i>0\).
\end{lemma}

\begin{proof}
  Write \(W=\Spec A\) and \(\mathcal F=\widetilde M\).  The section functor is
  \(M\mapsto M\), hence exact on the category of \(A\)-modules; its derived
  functors vanish in positive degree.
\end{proof}

\begin{lemma}[Relative curves have no higher coherent cohomology]
  \label{mk-lem-curve-h2-vanishing}
  \dcref{III.1}
  \uses{mk-prop-cech-computes}
  \cite{stacks-cohomology-schemes}
  For every \(k\)-scheme \(T\) and quasi-coherent \(\mathcal F\) on \(C_T\),
  \(H^i(C_T,\mathcal F)=0\) for \(i\ge2\).
\end{lemma}

\begin{proof}
  Base change preserves the finite affine cover and affine intersections.
  The resulting Cech complex has no terms above degree one, so its cohomology
  vanishes in degrees \(i\ge2\).
\end{proof}

\begin{proposition}[Flat scalar extension of the Cech complex]
  \label{mk-prop-cech-flat-base-change}
  \dcref{III.12}
  \uses{mk-def-cech-complex}
  \cite{stacks-cohomology-schemes}
  For a field extension \(k\subset k'\), the Cech complex for
  \(\mathcal F_{k'}\) is canonically
  \(\check C^\bullet(\mathcal F)\otimes_k k'\).
\end{proposition}

\begin{proof}
  Sections of a quasi-coherent sheaf on an affine are the corresponding
  module, and localization and tensor product commute for the flat extension
  \(k\to k'\).  This identifies both terms and the restriction differential.
\end{proof}

\begin{lemma}[Cohomology commutes with flat extension]
  \label{mk-lem-cech-flat-cohomology}
  \dcref{III.12}
  \uses{mk-prop-cech-flat-base-change,mk-prop-cech-computes}
  \cite{stacks-cohomology-schemes}
  Tensoring the two-affine Cech complex with \(k'\) gives
  \(H^i(C,\mathcal F)\otimes_k k'\cong H^i(C_{k'},\mathcal F_{k'})\).
\end{lemma}

\begin{proof}
  A field extension is flat, so kernels and cokernels of the Cech differential
  commute with tensor product.  Use \ref{mk-prop-cech-computes} on both curves.
\end{proof}

\begin{theorem}[Cohomology and base change]
  \label{mk-thm-cohomology-base-change}
  \dcref{III.12}
  \uses{mk-def-genus}
  \cite{stacks-project,stacks-cohomology-schemes}
  For a coherent sheaf \(\mathcal F\) on \(C\), \(H^i(C,\mathcal F)\) is
  finite-dimensional over \(k\).  If \(k\to k'\) is a field extension, then
  \[
    H^i(C,\mathcal F)\otimes_k k'\cong
    H^i(C_{k'},\mathcal F_{k'}).
  \]
\end{theorem}

\begin{proof}
  A finite affine cover of the proper curve gives a bounded Cech complex of
  finitely generated \(k\)-modules computing the cohomology of a coherent
  sheaf.  Hence each cohomology group is finite-dimensional.  After extending
  scalars to \(k'\), the same cover computes the base-changed sheaf and every
  term of the complex is tensored with \(k'\).  Since field extensions are
  flat, tensoring commutes with taking cohomology, which gives the canonical
  isomorphism.
\end{proof}

\begin{proposition}[Global functions]
  \label{mk-prop-global-functions}
  \dcref{III.1}
  \cite{hartshorne-ag,stacks-schemes}
  If \(C\) is geometrically integral and proper over \(k\), then
  \(H^0(C,\mathcal O_C)=k\).
\end{proposition}

\begin{proof}
  Properness makes \(H^0(C,\mathcal O_C)\) a finite \(k\)-algebra.  Apply the
  base-change theorem to \(i=0\) and an algebraic closure \(\bar k\):
  \[
    H^0(C,\mathcal O_C)\otimes_k\bar k
      \cong H^0(C_{\bar k},\mathcal O_{C_{\bar k}}).
  \]
  The scheme \(C_{\bar k}\) is proper and integral, so its global functions
  form a finite field extension of \(\bar k\), hence equal \(\bar k\).
  Consequently \(H^0(C,\mathcal O_C)\) has \(k\)-dimension one and the
  structural inclusion \(k\hookrightarrow H^0(C,\mathcal O_C)\) is an
  isomorphism.
\end{proof}

\begin{proposition}[The structure sheaf controls the tangent dimension]
  \label{mk-prop-genus-tangent}
  \dcref{5.11,custom}
  \uses{mk-def-genus,mk-thm-cohomology-base-change}
  \cite{kleiman-picard}
  For the identity of the Picard scheme, the Zariski tangent space satisfies
  \[
    T_0\operatorname{Pic}_{C/k}\cong H^1(C,\mathcal O_C).
  \]
  In particular its dimension is \(g(C)\), and this identification commutes
  with extension of the ground field.
\end{proposition}

\begin{proof}
  Let \(k[\epsilon]=k[\epsilon]/(\epsilon^2)\).  The kernel of
  \(\operatorname{Pic}_{C/k}(k[\epsilon])\to\operatorname{Pic}_{C/k}(k)\)
  consists of line bundles on \(C_{k[\epsilon]}\) restricting to the trivial
  bundle.  The exact sequence of sheaves
  \[
    1\longrightarrow 1+\epsilon\mathcal O_C
    \longrightarrow\mathcal O_{C_{k[\epsilon]}}^\times
    \longrightarrow\mathcal O_C^\times\longrightarrow1
  \]
  identifies \(1+\epsilon\mathcal O_C\) with the additive sheaf
  \(\mathcal O_C\).  Taking cohomology identifies this kernel, and hence the
  tangent space at the identity, with \(H^1(C,\mathcal O_C)\).  Replacing
  \(\epsilon\) by \(a\epsilon\) gives the \(k\)-vector-space structure, and
  the base-change statement follows from the preceding theorem.
\end{proof}

\label{mk-ch-picard}

\begin{definition}[Rigidified line bundle]
  \label{mk-def-rigidified-line-bundle}
  \dcref{2.2}
  \cite{kleiman-picard}
  If \(T\) has a section \(s:T\to C_T\), a rigidified line bundle is a pair
  \((\mathcal L,\phi)\) with \(\phi:s^*\mathcal L\cong\mathcal O_T\).
\end{definition}

\begin{lemma}[Rigidification removes the base ambiguity]
  \label{mk-lem-rigidification-quotient}
  \dcref{2.2}
  \uses{mk-def-picard-functor,mk-def-rigidified-line-bundle}
  \cite{kleiman-picard}
  Pullback along \(C_T\to T\) identifies the kernel of restriction to the
  section with \(\operatorname{Pic}(T)\).  Thus rigidified classes represent
  \(\operatorname{Pic}^{\sharp}_{C/k}(T)\).
\end{lemma}

\begin{proof}
  A pullback \(p^*\mathcal M\) has the canonical rigidification
  \(s^*p^*\mathcal M=\mathcal M\).  Conversely, an isomorphism of two
  representatives restricts along \(s\) to a line bundle on \(T\); tensoring
  by its inverse makes the isomorphism rigidified.  The remaining ambiguity is
  exactly tensoring by a line bundle pulled back from \(T\).
\end{proof}

\begin{lemma}[Pullback of divisor bundles]
  \label{mk-lem-divisor-bundle-base-change}
  \dcref{3.7}
  \uses{mk-def-relative-divisor}
  \cite{kleiman-picard}
  For \(T'\to T\) and a relative effective divisor \(D\subset C_T\),
  \[
    \mathcal O_{C_{T'}}(D_{T'})\cong
    \mathcal O_{C_T}(D)\big|_{C_{T'}}.
  \]
\end{lemma}

\begin{proof}
  The ideal of a relative effective Cartier divisor is invertible and remains
  invertible after pullback.  Dualising the pulled-back ideal gives the stated
  identification.
\end{proof}

\begin{proposition}[The relative Picard sheaf is a sheaf]
  \label{mk-prop-picard-sheaf}
  \dcref{2.2}
  \uses{mk-def-picard-functor,mk-lem-rigidification-quotient}
  \cite{kleiman-picard}
  Isomorphism classes of line bundles modulo pullbacks satisfy fppf descent;
  hence the associated fppf sheaf is computed by locally defined classes with
  the usual cocycle condition.
\end{proposition}

\begin{proof}
  Line bundles form a stack for the fppf topology.  Descent data are
  effective and two descended bundles differ by a line bundle on the base,
  which is precisely the quotient relation in the definition.
\end{proof}

\begin{lemma}[Tensor product respects rigidification]
  \label{mk-lem-rigidified-tensor}
  \dcref{2.2}
  \uses{mk-def-rigidified-line-bundle}
  \cite{kleiman-picard}
  Tensor product, duality, and the trivial bundle preserve rigidifications and
  induce the group operations on rigidified classes.
\end{lemma}

\begin{proof}
  Restriction to \(s(T)\) turns tensor product into tensor product of the two
  trivializations; duality inverts it.  The canonical associativity and
  symmetry constraints satisfy the group axioms.
\end{proof}

\begin{proposition}[Relative degree is additive]
  \label{mk-prop-relative-degree-additive}
  \dcref{3.7}
  \uses{mk-def-relative-divisor,mk-lem-divisor-invertible}
  \cite{kleiman-picard}
  In a flat family, the degree of a relative effective divisor is locally
  constant, and
  \(\deg(\mathcal L\otimes\mathcal M)=\deg\mathcal L+\deg\mathcal M\).
\end{proposition}

\begin{proof}
  The degree is the rank of the finite locally free algebra
  \(\mathcal O_D\) over the base, hence locally constant.  On a geometric
  fibre, tensor product adds Cartier divisor classes; the assertion follows
  fibrewise and therefore in the family.
\end{proof}

\begin{definition}[Relative Picard functor]
  \label{mk-def-picard-functor}
  \dcref{2.2}
  \cite[Def.~2.2]{kleiman-picard}
  For \(T\in(\Sch/k)\), define
  \[
    \operatorname{Pic}^{\sharp}_{C/k}(T)=\operatorname{Pic}(C_T)/
    \operatorname{Pic}(T),
  \]
  where the quotient is by pullback along \(C_T\to T\).  Its associated
  fppf (and etale) sheaf is denoted \(\operatorname{Pic}_{C/k}\).
\end{definition}

\begin{definition}[Relative effective divisors]
  \label{mk-def-relative-divisor}
  \dcref{3.7}
  \cite[Thm.~3.7]{kleiman-picard}
  A relative effective divisor on \(C_T\) is a closed subscheme \(D\subset C_T\)
  that is finite and flat over \(T\).  The functor of such divisors is denoted
  \(\operatorname{Div}_{C/k}\).
\end{definition}

For a smooth relative curve, a finite flat effective Cartier divisor is the
same datum as a relative zero-cycle of degree locally constant on the base.

\begin{proposition}[The Abel map]
  \label{mk-prop-abel-map}
  \dcref{3.7}
  \uses{mk-def-relative-divisor,mk-def-picard-functor}
  \cite[Thm.~3.7]{kleiman-picard}
  The assignment \(D\mapsto\mathcal O_{C_T}(D)\) defines a natural morphism
  \[
    \operatorname{Div}_{C/k}\longrightarrow\operatorname{Pic}_{C/k}.
  \]
  On a geometric fibre it sends an effective divisor to its line-bundle class.
\end{proposition}

\begin{proof}
  An effective Cartier divisor \(D\) determines the invertible sheaf
  \(\mathcal O_{C_T}(D)\).  Pullback of Cartier divisors and of their
  associated line bundles commute with base change in \(T\).  Tensoring by a
  pullback from \(T\) changes the line bundle by the subgroup quotiented out
  in \(\operatorname{Pic}^{\sharp}_{C/k}\), so the construction descends to
  a natural map into the relative Picard sheaf.
\end{proof}

\begin{proposition}[Tensor law]
  \label{mk-prop-picard-group}
  \dcref{2.2}
  \uses{mk-def-picard-functor}
  \cite{kleiman-picard}
  Tensor product, the trivial line bundle, and duals make
  \(\operatorname{Pic}_{C/k}\) a commutative group-valued functor, naturally
  in \(T\).
\end{proposition}

\begin{proof}
  Tensor product is associative and symmetric up to the canonical
  isomorphisms of line bundles, the trivial bundle is the identity, and
  dualisation supplies inverses.  These operations commute with pullback to
  \(C_T\) and with tensoring by bundles pulled back from \(T\), so they define
  the commutative group structure on the quotient sheaf.
\end{proof}

\label{mk-ch-representability}

Fix a relatively ample line bundle on \(C\to\Spec k\).  For a Hilbert
polynomial \(P\), let \(\operatorname{Hilb}^P_{C/k}\) and
\(\operatorname{Quot}^P_{C/k}\) denote the corresponding functors.

\begin{definition}[Section module in a fixed twist]
  \label{mk-def-section-module}
  \dcref{4.8}
  \cite{kleiman-picard}
  For a line bundle \(\mathcal L\) and twist \(m\), write
  \(M_m(\mathcal L)=H^0(C,\mathcal L(m))\).
\end{definition}

\begin{lemma}[Finite generation of the section module]
  \label{mk-lem-section-module-finite}
  \dcref{4.8}
  \uses{mk-def-section-module}
  \cite{hartshorne-ag,kleiman-picard}
  \(M_m(\mathcal L)\) is finite-dimensional over \(k\), and in a flat family
  its formation is compatible with base change whenever
  \(H^1(C,\mathcal L(m))=0\).
\end{lemma}

\begin{proof}
  Coherent-cohomology finiteness gives finite dimension.  Cohomology and base
  change identifies sections after a field extension; vanishing of \(H^1\)
  removes the cokernel in the base-change exact sequence.
\end{proof}

\begin{lemma}[Effective divisors are flat length families]
  \label{mk-lem-effective-divisor-flat-length}
  \dcref{3.7}
  \cite{kleiman-picard}
  A relative effective divisor \(D\subset C_T\) is a finite locally free
  \(T\)-scheme, and its rank is its fibrewise degree.
\end{lemma}

\begin{proof}
  A relative Cartier divisor on a smooth relative curve has
  \(\mathcal O_D\) finite over \(\mathcal O_T\).  Flatness over \(T\) makes
  this finite module locally free, with rank equal to its geometric fibre
  length.
\end{proof}

\begin{proposition}[The divisor functor is a Hilbert open]
  \label{mk-prop-divisor-hilbert-open}
  \dcref{3.7}
  \uses{mk-lem-effective-divisor-flat-length,mk-thm-hilbert-quot}
  \cite{kleiman-picard,nitsure-hilbert-quot}
  The functor of degree-\(n\) relative effective divisors is represented by
  the open-and-closed length-\(n\) locus of \(\operatorname{Hilb}_{C/k}\).
\end{proposition}

\begin{proof}
  By \ref{mk-lem-effective-divisor-flat-length}, such a divisor is a flat
  family with constant Hilbert polynomial \(n\).  On a smooth curve every
  finite flat length-\(n\) subscheme is an effective Cartier divisor, so the
  two functors agree.  The Hilbert scheme theorem gives representability.
\end{proof}

\begin{lemma}[Large twists are generated and acyclic]
  \label{mk-lem-large-twist}
  \dcref{4.8}
  \uses{mk-thm-riemann-roch}
  \cite{hartshorne-ag,kleiman-picard}
  For a bounded set of degrees there is \(m\) such that every line bundle
  \(\mathcal L\) in that set satisfies
  \(H^1(C,\mathcal L(m))=0\) and is generated by its global sections.
\end{lemma}

\begin{proof}
  The first assertion is the large-degree vanishing
  \ref{mk-cor-large-degree}.  For a closed point \(P\), apply that vanishing
  to \(\mathcal L(m-P)\); the evaluation map at \(P\) is then surjective.
  Since this holds for every \(P\), the bundle is globally generated.
\end{proof}

\begin{proposition}[Quot parameterises generated line bundles]
  \label{mk-prop-quot-line-bundles}
  \dcref{4.8}
  \uses{mk-lem-large-twist,mk-thm-hilbert-quot}
  \cite{kleiman-picard,nitsure-hilbert-quot}
  With \(m\) as above, line bundles \(\mathcal L\) in the bounded range are
  represented by quotients
  \(H^0(C,\mathcal L(m))\otimes\mathcal O_C(-m)\twoheadrightarrow\mathcal L\)
  in a fixed Quot scheme.
\end{proposition}

\begin{proof}
  Global generation gives the evaluation quotient.  The Hilbert polynomial is
  fixed on the bounded degree range, so the quotient lies in one projective
  Quot component.  Conversely, the open locus where the quotient is invertible
  gives a line bundle with the prescribed polynomial.
\end{proof}

\begin{lemma}[Change of generators is the equivalence relation]
  \label{mk-lem-quot-generator-relation}
  \dcref{4.9}
  \uses{mk-prop-quot-line-bundles}
  \cite{kleiman-picard}
  Two Quot points give the same relative line-bundle class exactly when,
  fppf-locally on the base, they differ by an element of the corresponding
  general linear group.
\end{lemma}

\begin{proof}
  An isomorphism of the quotient line bundles carries one generating basis to
  the other, giving a change-of-generators matrix.  Conversely such a matrix
  identifies the two evaluation quotients.  Local freeness of the generating
  module makes this relation fppf-locally defined.
\end{proof}

\begin{proposition}[Quotient descent on a bounded degree range]
  \label{mk-prop-picard-quotient-descent}
  \dcref{4.9}
  \uses{mk-lem-quot-generator-relation,mk-prop-picard-sheaf}
  \cite{kleiman-picard}
  The fppf quotient of the invertible Quot locus by change of generators
  represents the corresponding open subfunctor of \(\operatorname{Pic}_{C/k}\).
\end{proposition}

\begin{proof}
  The relation is an effective fppf equivalence relation by descent for
  line bundles.  Its sheaf quotient has exactly the same \(T\)-points as
  relative line-bundle classes in the bounded range, and the quotient theorem
  supplies the representing scheme.
\end{proof}

\begin{theorem}[Hilbert and Quot representability]
  \label{mk-thm-hilbert-quot}
  \dcref{1.1}
  \cite{nitsure-hilbert-quot}
  The functors \(\operatorname{Hilb}^P_{C/k}\) and
  \(\operatorname{Quot}^P_{C/k}\) are represented by projective \(k\)-schemes.
  Their formation is compatible with base change.
\end{theorem}

\begin{proof}
  Choose a sufficiently positive embedding of \(C\) into projective space.
  A quotient with fixed Hilbert polynomial is generated in one bounded degree,
  so it is represented by a closed subscheme of a Grassmannian.  The
  flattening-stratification condition cuts out the desired Hilbert or Quot
  functor.  The resulting scheme is projective, and the construction commutes
  with arbitrary base change because Hilbert polynomials and flattening are
  preserved by base change.
\end{proof}

\begin{lemma}[Flattening stratification]
  \label{mk-lem-flattening-stratification}
  \dcref{1.1}
  \cite{nitsure-hilbert-quot}
  For a projective morphism and a coherent sheaf, there is a universal
  locally closed stratification of the base on which the sheaf is flat with a
  fixed Hilbert polynomial.
\end{lemma}

\begin{proof}
  Choose a finite graded presentation after a projective embedding.  Fitting
  ideals of the graded pieces cut out the loci with the prescribed ranks;
  these loci glue and satisfy the universal factorisation property.
\end{proof}

\begin{lemma}[Invertibility is open in a flat family]
  \label{mk-lem-invertibility-open}
  \dcref{4.8}
  \uses{mk-lem-flattening-stratification}
  \cite{kleiman-picard}
  In a flat family of rank-one quotients on a smooth curve, the locus where
  the quotient is invertible is open.
\end{lemma}

\begin{proof}
  The locally free locus of a flat coherent sheaf is open.  Rank one on the
  generic point and the fixed Hilbert polynomial make this the invertible locus.
\end{proof}

\begin{theorem}[Picard representability]
  \label{mk-thm-picard-representability}
  \dcref{4.8}
  \uses{mk-def-picard-functor,mk-def-relative-divisor,mk-thm-hilbert-quot}
  \cite[Thm.~4.8]{kleiman-picard}
  The sheaf \(\operatorname{Pic}_{C/k}\) is represented by a separated
  \(k\)-scheme \(\operatorname{Pic}_{C/k}\), locally of finite type, and
  \[
    \operatorname{Pic}_{C/k}=\coprod_{d\in\mathbb Z}\operatorname{Pic}^d_{C/k}
  \]
  with each degree piece open and quasi-projective.  The universal line bundle
  exists after rigidification along a section (and after etale descent without
  a section).
\end{theorem}

\begin{proof}
  For \(n\) large, Riemann--Roch gives
  \(H^1(C_T,\mathcal L(n))=0\) for every line bundle \(\mathcal L\) in a
  bounded degree range.  Such a line bundle is therefore represented by a
  quotient of a fixed vector bundle of sections, and the Quot scheme gives a
  parameter space.  Two quotients determine the same line bundle precisely
  when they differ by the change of basis of the chosen generators.  The
  resulting fppf equivalence relation is effective; its quotient is the
  corresponding open of the Picard sheaf.  Varying the degree and using
  compatibility on overlaps gives the separated, locally finite-type scheme
  \(\operatorname{Pic}_{C/k}\) and its degree decomposition.
\end{proof}

\begin{lemma}[Quotient presentation]
  \label{mk-lem-picard-quotient}
  \dcref{4.9}
  \uses{mk-thm-hilbert-quot,mk-thm-picard-representability}
  \cite[Lem.~4.9]{kleiman-picard}
  On every bounded degree range, a projective Hilbert/Quot scheme admits an
  fppf locally trivial equivalence relation whose quotient is the
  corresponding open subfunctor of \(\operatorname{Pic}_{C/k}\).
\end{lemma}

\begin{proof}
  On a bounded degree range, the preceding construction uses one fixed
  Quot scheme and a fixed number of generators.  The group of changes of
  generators acts on it, and the orbit relation is fppf locally trivial
  because a line bundle is locally generated by the chosen sections.  Descent
  for line bundles identifies the quotient sheaf with the indicated open
  subfunctor of \(\operatorname{Pic}_{C/k}\).
\end{proof}

\label{mk-ch-components}

\begin{lemma}[Degree is locally constant in families]
  \label{mk-lem-degree-locally-constant}
  \dcref{5.1}
  \uses{mk-prop-relative-degree-additive}
  \cite{kleiman-picard}
  The degree of a line bundle on \(C_T\) is locally constant on \(T\).
\end{lemma}

\begin{proof}
  Choose a relatively ample bundle and compute the Hilbert polynomial of the
  fibres.  Flatness makes this polynomial locally constant, and on a curve its
  linear coefficient is the degree.
\end{proof}

\begin{lemma}[Degree components are open and closed]
  \label{mk-lem-degree-open-closed}
  \dcref{5.1}
  \uses{mk-lem-degree-locally-constant,mk-thm-picard-representability}
  \cite{kleiman-picard}
  Each \(\operatorname{Pic}^d_{C/k}\) is an open-and-closed subfunctor of
  \(\operatorname{Pic}_{C/k}\).
\end{lemma}

\begin{proof}
  The degree function is locally constant by
  \ref{mk-lem-degree-locally-constant}; its inverse image of \(d\) is therefore
  open and closed.  Representability transfers this decomposition to schemes.
\end{proof}

\begin{lemma}[Translations identify degree components]
  \label{mk-lem-picard-translation-degree}
  \dcref{5.1}
  \uses{mk-prop-picard-group,mk-lem-degree-open-closed}
  \cite{kleiman-picard}
  If \(\mathcal M\) has degree \(r\), tensoring by \(\mathcal M\) gives an
  isomorphism
  \(\operatorname{Pic}^d_{C/k}\xrightarrow{\sim}
    \operatorname{Pic}^{d+r}_{C/k}\).
\end{lemma}

\begin{proof}
  Tensoring by \(\mathcal M\) is a morphism by the group law and adds degrees.
  Tensoring by \(\mathcal M^{-1}\) is its inverse.
\end{proof}

\begin{lemma}[The Abel map is proper]
  \label{mk-lem-abel-map-proper}
  \dcref{5.4}
  \uses{mk-prop-abel-map,mk-prop-divisor-hilbert-open}
  \cite{kleiman-picard}
  The morphism \(C^{(n)}\to\operatorname{Pic}^n_{C/k}\) is proper.
\end{lemma}

\begin{proof}
  The source is the projective length-\(n\) Hilbert scheme of the projective
  curve.  The target is separated, so the graph of the Abel map is closed;
  projection of this closed graph is proper.
\end{proof}

\begin{proposition}[Large-degree Abel map is surjective]
  \label{mk-prop-abel-surjective}
  \dcref{5.4}
  \uses{mk-cor-large-degree,mk-lem-abel-map-proper}
  \cite{kleiman-picard}
  If \(n>2g(C)-2\), then \(C^{(n)}\to\operatorname{Pic}^n_{C/k}\) is
  surjective.
\end{proposition}

\begin{proof}
  For every line bundle \(\mathcal L\) of degree \(n\), large-degree vanishing
  gives \(H^1(C,\mathcal L)=0\) and hence
  \(h^0(C,\mathcal L)=n+1-g(C)>0\).  A nonzero section has an effective zero
  divisor \(D\) with \(\mathcal L\cong\mathcal O_C(D)\).
\end{proof}

\begin{lemma}[The obstruction space for line bundles]
  \label{mk-lem-picard-obstruction}
  \dcref{5.11}
  \uses{mk-lem-curve-h2-vanishing}
  \cite{kleiman-picard}
  The obstruction to lifting a line bundle across a square-zero extension
  \(T_0\hookrightarrow T\) lies in \(H^2(C_{T_0},\mathcal O_{C_{T_0}})\).
\end{lemma}

\begin{proof}
  Choose local trivializations of the line bundle on an affine cover.  Lifts of
  transition functions differ by additive \(1\)-cochains; the obstruction to
  satisfying the cocycle condition is their \(2\)-coboundary class in the
  indicated cohomology group.
\end{proof}

\begin{proposition}[Smoothness from vanishing obstruction]
  \label{mk-prop-picard-smooth}
  \dcref{5.11}
  \uses{mk-lem-picard-obstruction,mk-lem-curve-h2-vanishing,mk-prop-picard-group}
  \cite{kleiman-picard}
  The Picard scheme is smooth at the identity, and therefore smooth on every
  component.
\end{proposition}

\begin{proof}
  The obstruction group in \ref{mk-lem-picard-obstruction} vanishes by
  \ref{mk-lem-curve-h2-vanishing}, so every infinitesimal lifting problem has a
  solution.  This is the infinitesimal criterion for smoothness at the identity;
  translations transport it to all points.
\end{proof}

\begin{definition}[Degree components]
  \label{mk-def-picard-degree}
  \dcref{2.2}
  \uses{mk-thm-picard-representability}
  \cite{kleiman-picard}
  The component \(\operatorname{Pic}^d_{C/k}\) is the locus of line bundles of
  degree \(d\).  Tensor product induces
  \[
    \operatorname{Pic}^d_{C/k}\times\operatorname{Pic}^e_{C/k}
    \longrightarrow\operatorname{Pic}^{d+e}_{C/k}.
  \]
\end{definition}

\begin{proof}
  The Hilbert polynomial of a line bundle on a curve is determined by its
  degree.  In a flat family the Hilbert polynomial is locally constant, hence
  the degree loci are open and closed.  The tensor law adds degrees, giving
  the displayed morphism.
\end{proof}

\begin{theorem}[Identity component]
  \label{mk-thm-identity-component}
  \dcref{5.1}
  \uses{mk-thm-picard-representability,mk-prop-picard-group}
  \cite[Lem.~5.1]{kleiman-picard}
  If \(G\) is a group scheme locally of finite type over a field, its connected
  component \(G^0\) containing the identity is an open and closed subgroup
  scheme, geometrically irreducible, and formation of \(G^0\) commutes with
  extension of the ground field.
\end{theorem}

\begin{proof}
  A locally finite-type group scheme is locally Noetherian.  Its connected
  components are open, and translations carry the component of the identity
  to every other component.  Inversion and multiplication therefore preserve
  the identity component, which is an open and closed subgroup.  After a
  field extension the same description holds on geometric points, so the
  component is geometrically irreducible and formation of \(G^0\) commutes
  with base change.
\end{proof}

\begin{theorem}[The Picard variety]
  \label{mk-thm-pic0-abelian}
  \dcref{5.4,5.11,5.13,5.14}
  \uses{mk-thm-identity-component,mk-prop-genus-tangent,mk-def-genus}
  \cite[Thms.~5.4 and 5.11, Cors.~5.13--5.14]{kleiman-picard}
  The identity component
  \[
    \operatorname{Pic}^0_{C/k}:=(\operatorname{Pic}_{C/k})^0
  \]
  is a smooth, proper, geometrically connected commutative group scheme over
  \(k\), hence an abelian variety, and
  \[
    \dim\operatorname{Pic}^0_{C/k}=g(C).
  \]
\end{theorem}

\begin{proof}
  For \(n>2g(C)-2\), every degree-\(n\) line bundle has vanishing \(H^1\), and
  the Abel map from the proper scheme \(C^{(n)}\) is surjective onto
  \(\operatorname{Pic}^n_{C/k}\).  Translation by a fixed line bundle
  identifies this component with \(\operatorname{Pic}^0_{C/k}\), proving
  properness.  The tangent-space computation gives
  \[
    \dim T_0\operatorname{Pic}_{C/k}=\dim_kH^1(C,\mathcal O_C)=g(C).
  \]
  Since \(H^2(C,\mathcal O_C)=0\), the infinitesimal lifting obstruction for
  line bundles vanishes; the Picard scheme is smooth at the identity and
  hence everywhere by translation.  The identity-component theorem supplies
  geometric connectedness and the group structure, so
  \(\operatorname{Pic}^0_{C/k}\) is an abelian variety of dimension \(g(C)\).
\end{proof}

\label{mk-ch-rigidity}

\begin{theorem}[Rigidity lemma]
  \label{mk-thm-rigidity}
  \dcref{I.2}
  \cite{milne-av,mumford-av}
  Let \(X\) be proper and geometrically connected over \(k\), \(Y\) a reduced
  \(k\)-scheme, and \(f:X\times_kY\to A\) a morphism to an abelian variety.
  If \(f|_{\{x_0\}\times Y}\) is constant, then \(f\) factors uniquely through
  \(X\).  If \(f(x_0,y_0)=0\) and both coordinate restrictions vanish at the
  base points, then
  \[
    f(x,y)=f(x,y_0)+f(x_0,y).
  \]
\end{theorem}

\begin{proof}
  The assertion is unchanged after extending \(k\), so assume it is
  algebraically closed.  Choose an affine neighbourhood \(U\) of the common
  value on \(\{x_0\}\times Y\).  Properness makes the set of \(x\) for which
  \(f(\{x\}\times Y)\) leaves
  \(U\) closed.  On its complement, regular
  functions on \(U\) pull back to functions on \(Y\), and their values are
  fixed by \(x_0\); they are therefore constant.  The equalizer with the
  resulting map \(X\to A\) is closed because \(A\) is separated and contains
  a dense open of the reduced scheme \(X\times Y\), so it is all of
  \(X\times Y\).  Apply this factorisation to
  \(f(x,y)-f(x,y_0)-f(x_0,y)\) to obtain the displayed identity.
\end{proof}

\begin{lemma}[Pointed maps of abelian varieties are homomorphisms]
  \label{mk-lem-pointed-abelian-homomorphism}
  \dcref{I.2}
  \uses{mk-thm-rigidity}
  \cite{milne-av,mumford-av}
  A morphism \(u:A\to B\) of abelian varieties with \(u(0)=0\) is a group
  homomorphism.
\end{lemma}

\begin{proof}
  Apply the decomposition in the rigidity lemma to
  \(F(x,y)=u(x+y)-u(x)-u(y)\).  Both coordinate restrictions are zero, so
  \(F=0\).
\end{proof}

\begin{lemma}[Graph closure of a rational map]
  \label{mk-lem-rational-graph-proper}
  \dcref{3.1}
  \cite{milne-av}
  If \(A\) is proper and \(f:X\dashrightarrow A\) is rational, the closure
  of its graph is proper and birational over \(X\).
\end{lemma}

\begin{proof}
  The graph is closed over the domain of \(f\).  Its closure has proper
  projection to \(X\), being closed in \(X\times A\), and the projection is an
  isomorphism over the dense domain.
\end{proof}

\begin{lemma}[Codimension-one points on a nonsingular variety]
  \label{mk-lem-codim-one-dvr}
  \dcref{3.2}
  \cite{milne-av,hartshorne-ag}
  At a codimension-one point of a nonsingular variety, the local ring is a DVR.
\end{lemma}

\begin{proof}
  Nonsingularity means regularity.  A height-one regular local domain has
  principal maximal ideal and dimension one, hence is a discrete valuation ring.
\end{proof}

\begin{definition}[Rational map domain]
  \label{mk-def-rational-map}
  \dcref{3.1}
  \cite{milne-av}
  A rational map \(X\dashrightarrow Y\) is a class of morphisms from dense
  open subsets of \(X\); its maximal domain is denoted \(\operatorname{Dom}(f)\).
\end{definition}

\begin{lemma}[Generic agreement]
  \label{mk-lem-rational-generic-agreement}
  \dcref{3.1}
  \uses{mk-def-rational-map}
  \cite{milne-av}
  For integral \(X\) and separated \(Y\), rational maps agreeing at the
  generic point agree as rational maps.
\end{lemma}

\begin{proof}
  The equalizer of two representatives is closed and contains the generic
  point, hence contains a dense open of the integral intersection.
\end{proof}

\begin{lemma}[Singleton graph fibres imply extension]
  \label{mk-lem-singleton-graph-extension}
  \dcref{3.2}
  \uses{mk-lem-rational-graph-proper,mk-lem-codim-one-dvr}
  \cite{milne-av}
  If the graph closure of \(f:X\dashrightarrow A\) has one point over every
  \(x\in X\), then it is the graph of a unique morphism \(X\to A\).
\end{lemma}

\begin{proof}
  The graph projection is proper and quasi-finite, hence finite.  Since \(X\)
  is nonsingular, a finite birational map to \(X\) is an isomorphism; compose
  its inverse with the second projection.
\end{proof}

\begin{theorem}[Extension of rational maps]
  \label{mk-thm-rational-extension}
  \dcref{3.1,3.2}
  \uses{mk-thm-rigidity,mk-lem-rational-graph-proper,mk-lem-codim-one-dvr,
    mk-lem-singleton-graph-extension}
  \cite[Thms.~3.1--3.2]{milne-av}
  A rational map from a nonsingular variety to an abelian variety extends to a
  unique morphism.  In particular a rational map from a smooth proper curve to
  an abelian variety has no indeterminacy.
\end{theorem}

\begin{proof}
  Let \(U\) be the domain of definition of the rational map and let
  \(Z\) be its graph closure in \(X\times A\).  Properness of \(A\) makes
  \(Z\to X\) proper and birational.  At a codimension-one point of the
  nonsingular source, the local ring is a discrete valuation ring, so the
  valuative criterion gives a unique point of \(A\) above it.  Thus the
  indeterminacy locus has codimension at least two.  Regular functions on the
  abelian variety are constant along the fibres of \(Z\to X\) by rigidity;
  consequently the graph has only one point over every source point and
  \(Z\to X\) is an isomorphism.  This supplies the unique extension.  For a
  smooth proper curve the same argument is just the valuative criterion at
  its closed points.
\end{proof}

\label{mk-ch-abel-jacobi}

Fix \(P_0\in C(k)\) and set \(J=\operatorname{Pic}^0_{C/k}\).

\begin{lemma}[The diagonal is an effective Cartier divisor]
  \label{mk-lem-diagonal-cartier}
  \dcref{III.6}
  \cite{hartshorne-ag,milne-av}
  The diagonal \(\Delta\subset C\times_kC\) is an effective Cartier divisor.
\end{lemma}

\begin{proof}
  The diagonal is a regular immersion of codimension one because \(C/k\) is
  smooth of relative dimension one.  A regular codimension-one immersion is
  effective Cartier.
\end{proof}

\begin{lemma}[The pointed diagonal bundle is rigidified]
  \label{mk-lem-pointed-diagonal-rigidified}
  \dcref{III.6}
  \uses{mk-lem-diagonal-cartier}
  \cite{milne-av}
  The bundle
  \(\mathcal P=\mathcal O(\Delta-C\times P_0-P_0\times C)\) restricts
  trivially to both \(C\times\{P_0\}\) and \(\{P_0\}\times C\).
\end{lemma}

\begin{proof}
  Restriction of \(\Delta\) to either axis is the point \(P_0\), while the
  corresponding fibre contributes the same divisor and the other fibre is
  disjoint.  The two restrictions are therefore \(\mathcal O_C\), with their
  canonical trivializations.
\end{proof}

\begin{lemma}[The ordered Abel map]
  \label{mk-lem-ordered-abel-map}
  \dcref{III.6}
  \uses{mk-def-abel-jacobi}
  \cite{milne-av}
  The map \(C^n\to J\), \((Q_1,\dots,Q_n)\mapsto
  \sum_i[\mathcal O_C(Q_i-P_0)]\), is a morphism.
\end{lemma}

\begin{proof}
  It is the \(n\)-fold composite of \(\iota_{P_0}\) with the group law on
  \(J\), hence is a morphism.
\end{proof}

\begin{lemma}[Symmetric descent of the ordered Abel map]
  \label{mk-lem-symmetric-abel-descent}
  \dcref{III.6}
  \uses{mk-lem-ordered-abel-map}
  \cite{milne-av}
  The ordered Abel map is invariant under \(S_n\) and descends uniquely to
  \(C^{(n)}\).
\end{lemma}

\begin{proof}
  Permuting the \(Q_i\) permutes tensor factors of the associated line bundle;
  the symmetry constraint gives equality in the commutative Picard group.
  The quotient property of \(C^{(n)}\) gives the descent.
\end{proof}

\begin{lemma}[Fibres of the Abel map are complete linear systems]
  \label{mk-lem-abel-fibre-linear-system}
  \dcref{III.6}
  \uses{mk-def-divisor,mk-def-divisor-line-bundle}
  \cite{milne-av,hartshorne-ag}
  Two effective divisors \(D,E\) of the same degree have the same image in
  \(\operatorname{Pic}^n_{C/k}\) exactly when \(D-E\) is principal; hence a
  geometric fibre is \(|D|\cong\PP H^0(C,\mathcal O_C(D))\).
\end{lemma}

\begin{proof}
  Equality of the line-bundle classes gives a rational function
  \(f\) with \(E=D+\operatorname{div}(f)\), and the converse is immediate.
  Effective divisors linearly equivalent to \(D\) are the zero divisors of
  nonzero sections of \(\mathcal O_C(D)\), modulo scalar multiplication.
\end{proof}

\begin{lemma}[Large-degree Abel map is surjective]
  \label{mk-lem-abel-jacobi-surjective}
  \dcref{III.6}
  \uses{mk-cor-large-degree,mk-lem-abel-fibre-linear-system}
  \cite{milne-av}
  For \(n\ge2g(C)-1\), every degree-\(n\) line bundle is represented by an
  effective divisor.
\end{lemma}

\begin{proof}
  Riemann--Roch and large-degree vanishing give
  \(h^0(C,\mathcal L)=n+1-g(C)>0\) for every \(\deg\mathcal L=n\).  The zero
  divisor of a nonzero section represents \(\mathcal L\).
\end{proof}

\begin{lemma}[Constancy on a linear system]
  \label{mk-lem-map-constant-on-linear-system}
  \dcref{III.6}
  \uses{mk-lem-abel-fibre-linear-system,mk-thm-rigidity}
  \cite{milne-av}
  A morphism from a complete linear system \(|D|\cong\PP^r\) to an abelian
  variety is constant.
\end{lemma}

\begin{proof}
  A projective space is proper and connected.  Apply the rigidity lemma to
  the morphism \(\PP^r\times\Spec k\to A\); its image is a complete connected
  subscheme of an affine neighbourhood of \(A\), hence a point.
\end{proof}

\begin{definition}[Abel--Jacobi map]
  \label{mk-def-abel-jacobi}
  \dcref{III.6}
  \uses{mk-thm-pic0-abelian}
  \cite{milne-av,mumford-av}
  The line bundle
  \(\mathcal O_{C\times C}(\Delta-C\times P_0-P_0\times C)\), rigidified
  along \(P_0\), defines
  \[
    \iota_{P_0}:C\longrightarrow J,\qquad
    Q\longmapsto[\mathcal O_C(Q-P_0)].
  \]
\end{definition}

\begin{proof}
  The diagonal is an effective Cartier divisor on \(C\times C\).  Subtracting
  the two fibres through \(P_0\) makes its associated line bundle trivial on
  both \(P_0\times C\) and \(C\times P_0\), so it is rigidified.  Restriction
  to \(C\times\{Q\}\) gives \(\mathcal O_C(Q-P_0)\), and the universal
  property of the Picard scheme produces the morphism \(\iota_{P_0}\).
\end{proof}

\begin{theorem}[Symmetric powers]
  \label{mk-thm-symmetric-powers}
  \dcref{III.6}
  \uses{mk-def-abel-jacobi,mk-thm-pic0-abelian}
  \cite{milne-av}
  For \(n\ge1\), the symmetric power \(C^{(n)}\) is smooth and proper and the
  sum of \(n\) copies of \(\iota_{P_0}\) descends to
  \[
    \alpha_n:C^{(n)}\longrightarrow J,\qquad
    D\longmapsto[\mathcal O_C(D-nP_0)].
  \]
  Its geometric fibres are the complete linear systems of divisors in the
  corresponding class.
\end{theorem}

\begin{proof}
  The Hilbert scheme of length-\(n\) subschemes of a smooth curve is smooth
  and represents effective relative divisors; it is denoted \(C^{(n)}\).
  Locally, a divisor is given by a monic polynomial and the elementary
  symmetric functions provide smooth coordinates.  The tensor product of the
  \(n\) pulled-back rigidified line bundles is invariant under permutations,
  hence descends to \(\alpha_n\).  Two effective divisors have the same image
  exactly when their difference is principal, so the fibre over a line-bundle
  class is its complete linear system.
\end{proof}

\begin{theorem}[Albanese property]
  \label{mk-thm-abel-jacobi-universal}
  \dcref{III.6}
  \uses{mk-def-abel-jacobi,mk-thm-symmetric-powers,mk-thm-rigidity}
  \cite{milne-av}
  If \(A\) is an abelian variety over \(k\) and \(f:C\to A\) satisfies
  \(f(P_0)=0\), there is a unique homomorphism \(u:J\to A\) such that
  \[
    f=u\circ\iota_{P_0}.
  \]
  Thus \(J\) is the Albanese variety of \((C,P_0)\).
\end{theorem}

\begin{proof}
  For \(n\ge 2g(C)-1\), Riemann--Roch makes
  \(\alpha_n:C^{(n)}\to\operatorname{Pic}^n_{C/k}\) surjective.  Given
  \(f(P_0)=0\), the sum of the values of \(f\) on an ordered \(n\)-tuple is
  symmetric and therefore descends to a morphism
  \(f_n:C^{(n)}\to A\).  On every complete linear system its restriction is
  constant: a morphism from a projective space to an abelian variety is
  constant by the rigidity lemma.  Hence \(f_n\) factors uniquely through
  \(\alpha_n\), giving a morphism \(u_n:\operatorname{Pic}^n_{C/k}\to A\).
  Translating by a degree-\(n\) line bundle identifies this with a morphism
  \(u:J\to A\).  The construction with \(n+1\) and the divisor
  \(P_0\) shows \(u\) is a homomorphism and \(f=u\circ\iota_{P_0}\).
  Surjectivity of \(\alpha_n\) proves uniqueness.
\end{proof}

\label{mk-ch-jacobian}

\begin{definition}[Degree-zero Picard functor]
  \label{mk-def-pic0-functor}
  \dcref{5.1}
  \uses{mk-def-picard-functor,mk-lem-degree-open-closed}
  \cite{kleiman-picard}
  For a \(k\)-scheme \(T\), \(\operatorname{Pic}^0_{C/k}(T)\) is the
  identity component of the represented relative Picard group after base
  change to \(T\).
\end{definition}

\begin{lemma}[Degree-zero classes are stable under base change]
  \label{mk-lem-pic0-base-change}
  \dcref{5.1}
  \uses{mk-def-pic0-functor,mk-lem-cech-flat-cohomology}
  \cite{kleiman-picard}
  For every field extension \(k\subset k'\),
  \[
    (\operatorname{Pic}^0_{C/k})_{k'}\cong
    \operatorname{Pic}^0_{C_{k'}/k'}.
  \]
\end{lemma}

\begin{proof}
  Base change preserves the tensor law and the identity section.  By
  \ref{mk-lem-degree-open-closed}, the degree-zero locus is open and closed;
  the connected component containing the identity is therefore carried to
  the corresponding component after base change.
\end{proof}

\begin{proposition}[Functoriality for morphisms of pointed curves]
  \label{mk-prop-jacobian-functorial}
  \dcref{III.6}
  \uses{mk-def-jacobian,mk-def-abel-jacobi}
  \cite{milne-av}
  A morphism \(u:C\to C'\) with \(u(P_0)=P'_0\) induces
  \(u^*:\operatorname{Jac}(C')\to\operatorname{Jac}(C)\), and
  \(u^*\circ\iota_{P'_0}=\iota_{P_0}\circ u\).
\end{proposition}

\begin{proof}
  Pullback preserves tensor products, inverses, and degree, so it restricts to
  the identity components.  Pulling back
  \(\mathcal O_{C'}(Q'-P'_0)\) gives
  \(\mathcal O_C(u^{-1}Q'-P_0)\); the diagonal description gives the stated
  compatibility.
\end{proof}

\begin{definition}[Jacobian]
  \label{mk-def-jacobian}
  \dcref{III.6}
  \uses{mk-thm-pic0-abelian}
  \cite{milne-av,kleiman-picard}
  The Jacobian of \(C/k\) is
  \[
    \operatorname{Jac}(C):=\operatorname{Pic}^0_{C/k}.
  \]
\end{definition}

\begin{theorem}[Jacobian package]
  \label{mk-thm-jacobian-package}
  \dcref{III.6,5.13,5.14,custom}
  \uses{mk-def-jacobian,mk-thm-abel-jacobi-universal,mk-thm-pic0-abelian}
  \cite{milne-av,kleiman-picard}
  By \ref{mk-thm-pic0-abelian}, the scheme \(\operatorname{Jac}(C)\) is an
  abelian variety of dimension \(g(C)\).  The map \(\iota_{P_0}\) is independent
  of the chosen base point up to translation, and it satisfies the universal
  property in \ref{mk-thm-abel-jacobi-universal}.
\end{theorem}

\begin{proof}
  The Picard-variety theorem identifies \(\operatorname{Pic}^0_{C/k}\) with
  an abelian variety and computes its dimension as \(g(C)\).  The
  Abel--Jacobi universal property then gives the stated factorisation for
  every pointed map from \(C\) to an abelian variety.  If \(P_1\) replaces
  \(P_0\), the two maps differ by the translation
  \(Q\mapsto Q-[\mathcal O_C(P_1-P_0)]\), by the tensor law.
\end{proof}

\begin{theorem}[Base change]
  \label{mk-thm-jacobian-base-change}
  \dcref{III.6,custom}
  \uses{mk-def-jacobian,mk-thm-picard-representability}
  \cite{kleiman-picard}
  For every field extension \(k\subset k'\),
  \[
    \operatorname{Jac}(C)\times_k k'\cong
    \operatorname{Jac}(C\times_k k').
  \]
  The isomorphism is canonical and compatible with towers of extensions and
  with Abel--Jacobi maps.
\end{theorem}

\begin{proof}
  Picard representability and the cohomology-and-base-change theorem identify
  the base change of each degree component with the corresponding component
  for \(C_{k'}\).  The identity section and tensor law are preserved by this
  identification, so the identity components agree.  Restricting to degree
  zero gives the canonical isomorphism of Jacobians, and the construction of
  the diagonal line bundle shows compatibility with Abel--Jacobi maps.
\end{proof}


